import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mul, add, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Root container
  const root = new ctx.THREE.Group();
  root.userData.handlers = {};

  // Geometry – aspect based on atlas region (512 x 320)
  const aspect = 512 / 320; // 1.6
  const geometry = new ctx.THREE.PlaneGeometry(aspect, 1);

  // Material – basic node material, will receive texture later
  const material = new MeshBasicNodeMaterial();
  material.transparent = true; // allow fade‑in if needed

  // Default UV (full texture). Will be replaced with atlas‑offset UV once texture loads.
  material.uvNode = uv();

  // Mesh
  const mesh = new ctx.THREE.Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously, but keep function synchronous
  let loadedTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTexture = tex;
    material.map = tex;
    // Atlas region is the whole texture (0,0,512,320) → no offset/scale needed.
    // If a sub‑region were required, replace the uvNode with a transformed version:
    // const uScale = 512 / tex.image.width;
    // const vScale = 320 / tex.image.height;
    // const uOffset = 0 / tex.image.width;
    // const vOffset = 0 / tex.image.height;
    // material.uvNode = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));
    material.needsUpdate = true;
  });

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
    // No GSAP timelines in this node, but kill any that might be added later.
    gsap.globalTimeline.clear();
  };

  return root;
}
